class Solution:
    def containsDuplicate(self, nums: List[int]) -> bool:
        # Approach 1: Early exit using a set for O(N) time
        seen = set()
        for num in nums:
            if num in seen:
                return True
            seen.add(num)
        return False

class Solution:
    def longestConsecutive(self, nums: List[int]) -> int:
        num_set = set(nums)
        ans = 0

        for num in num_set:
            # Only start counting from the beginning of a sequence
            if num - 1 not in num_set:
                length = 1
                current = num

                while current + 1 in num_set:
                    current += 1
                    length += 1

                ans = max(ans, length)

        return ans
